window.TESTS = window.TESTS || [];
TESTS.push({
id: 1, name: "多益 1",
sets: [
{ part: 5, title: "Part 5 單句填空", qs: [
{n:1,q:"_____ newer employees, senior workers tend to harbor deep loyalty towards the company.",qz:"不像較新進的員工，資深員工往往對公司懷有深厚的忠誠。",o:["Unlike","Through","Until","Among"],oz:["不像","透過","直到","在…之中"],a:0,ex:"句意是「新員工」與「資深員工」的對比，用介系詞 Unlike（不像…）。Through／Until／Among 語意都不通。"},
{n:2,q:"The conference _____ by more than one hundred management executives last week.",qz:"上週有超過一百位管理階層主管出席了這場會議。",o:["attendance","was attended","attends","is attended"],oz:["出席（名詞）","被出席（過去被動）","出席（現在主動）","被出席（現在被動）"],a:1,ex:"主詞 conference 是「被出席」的，且有 by + 行為者 → 被動語態；last week 表過去 → was attended。"},
{n:3,q:"The politician promised that after he was elected, he would _____ in a new age of peace.",qz:"那位政治人物承諾，當選後他將開創一個和平的新時代。",o:["take","usher","consider","generate"],oz:["拿","引領","考慮","產生"],a:1,ex:"固定片語 usher in（開啟、迎來新時代）。take in／generate in 不是此意，consider 不接 in。"},
{n:4,q:"The firm's partners discussed the situation thoroughly, _____ left the meeting still unclear as to the organization's future.",qz:"公司的合夥人們徹底討論了情況，然而離開會議時仍對組織的未來不明朗。",o:["without","therefore","including","yet"],oz:["沒有","因此","包括","然而"],a:3,ex:"前後語意轉折（討論得很徹底，卻仍不清楚），且連接兩個動詞片語 → 對等連接詞 yet（然而）。therefore 是副詞，語意也不對。"},
{n:5,q:"Sometimes, I have trouble telling _____ lunch box is supposed to be mine.",qz:"有時候，我分不清楚哪個便當盒才是我的。",o:["when","my","that","which"],oz:["何時","我的","那個","哪一個"],a:3,ex:"telling 後接名詞子句，lunch box 前需要疑問限定詞「哪一個」→ which lunch box。"},
{n:6,q:"Every time I hear the phone, I think it might be bad news, and I get this _____ feeling in my stomach.",qz:"每次聽到電話響，我就覺得可能是壞消息，胃裡會有一種往下沉的感覺。",o:["sink","sunk","sank","sinking"],oz:["下沉（原形）","過去分詞","過去式","下沉的（現在分詞）"],a:3,ex:"冠詞 this 與名詞 feeling 之間需要形容詞；a sinking feeling 是固定說法，指「不祥、心往下沉的感覺」。"},
{n:7,q:"Barbara had only been _____ staff for three weeks before the accident occurred.",qz:"在事故發生前，芭芭拉才剛到職三個星期。",o:["in","at","on","for"],oz:["在…裡","在","在…上（編制內）","為了"],a:2,ex:"be on (the) staff 為固定用法，表示「是…的正式員工、在編制內」。"},
{n:8,q:"You can't have it _____ ways; it's either one or the other.",qz:"你不能兩者都要；只能二選一。",o:["no","your","both","neither"],oz:["沒有","你的","兩者","兩者皆不"],a:2,ex:"慣用語 have it both ways（兩全其美、兩邊好處都要），後句 either one or the other 也提示是「兩個」。"},
{n:9,q:"When it comes to negotiating, I don't compromise. I want the highest value for the _____ cost.",qz:"說到談判，我不妥協。我要用最低的成本換取最高的價值。",o:["lowest","low","lowering","lowly"],oz:["最低的","低的","降低中的","卑微的"],a:0,ex:"與前面 the highest value 對稱，用最高級 the lowest cost。"},
{n:10,q:"I prefer spicy food, so I find the food here too _____ to be enjoyable.",qz:"我偏好辛辣的食物，所以覺得這裡的食物太淡而無味，吃得不盡興。",o:["ancient","delicate","tasteless","flavorful"],oz:["古老的","精緻的","無味的","美味的"],a:2,ex:"too … to …（太…以致於不能）表負面；喜歡辣的人覺得食物「沒味道」→ tasteless。"},
{n:11,q:"This is so _____! Why are you doing this now, in public?",qz:"這太丟臉了！你為什麼要現在、在大庭廣眾下做這種事？",o:["embarrassing","embarrassed","embarrasses","embarrassingly"],oz:["令人尷尬的","感到尷尬的","使尷尬（動詞）","尷尬地"],a:0,ex:"主詞 This 是「事情」，事情「令人尷尬」用 -ing 形容詞 embarrassing；-ed 用於人感到尷尬。"},
{n:12,q:"The protestors don't want the new power plant to be built _____ they fear a powerful earthquake may trigger a meltdown.",qz:"抗議者不希望興建新的發電廠，因為他們擔心強烈地震可能引發核心熔毀。",o:["furthermore","assuming that","due to","because"],oz:["此外","假設","由於（接名詞）","因為（接子句）"],a:3,ex:"空格後是完整子句 they fear…，表原因 → 連接詞 because。due to 後只能接名詞。"},
{n:13,q:"Excuse me. I think I'm getting another call. Can I put you on _____?",qz:"不好意思，我好像有另一通來電。可以請你稍等一下嗎？",o:["hold","pause","silence","speaker"],oz:["保留（稍候）","暫停","安靜","擴音"],a:0,ex:"電話用語 put someone on hold（讓對方在線上等候）。"},
{n:14,q:"I like Trevor because he always gives _____ instructions when managing complex projects.",qz:"我喜歡崔佛，因為他在管理複雜專案時總是給出清楚明確的指示。",o:["seen","visible","clear-cut","understanding"],oz:["被看見的","可見的","明確的","體諒的"],a:2,ex:"修飾 instructions（指示）且語意正面 → clear-cut（明確的、清楚的）。"},
{n:15,q:"I know Ron doesn't look _____, but he's the best player on the team.",qz:"我知道榮恩看起來不像運動員，但他是隊上最好的球員。",o:["athletically","athlete","athletics","athletic"],oz:["運動地（副詞）","運動員（名詞）","體育運動（名詞）","運動型的（形容詞）"],a:3,ex:"look 為連綴動詞，後接形容詞 → athletic。"},
{n:16,q:"_____ I don't believe in ghosts, I still think that old house on the hill is too creepy for me to enter.",qz:"雖然我不相信有鬼，但我還是覺得山丘上那棟老房子太陰森了，我不敢進去。",o:["Once","Even though","Now that","Whether"],oz:["一旦","雖然","既然","是否"],a:1,ex:"前後語意相反（不信鬼 vs. 還是不敢進去）→ 讓步連接詞 Even though。"},
{n:17,q:"It looks like a storm is _____, so we'd better go inside.",qz:"看起來暴風雨正在醞釀，我們最好進屋去。",o:["brewing","traversing","disturbing","augmenting"],oz:["醞釀中","橫越中","打擾中","增加中"],a:0,ex:"a storm is brewing 是固定說法（暴風雨即將來臨）。"},
{n:18,q:"All these items are painstakingly _____ with care and devotion by our in-house artisans.",qz:"這些商品全部由我們自家的工匠用心、費盡心力地親手製作。",o:["handcrafting","handcrafts","handcraft","handcrafted"],oz:["手工製作中","手工製作（第三人稱）","手工製作（原形）","被手工製作的"],a:3,ex:"items 是被製作的，are + p.p. 被動語態 → handcrafted；by our artisans 為行為者。"},
{n:19,q:"This division _____ unprofitable for six quarters. We have to reorganize.",qz:"這個部門已經連續六季沒有獲利了。我們必須進行重整。",o:["has been","should have been","would be","is being"],oz:["已經是（現在完成）","本應該是","將會是","正處於"],a:0,ex:"for six quarters 表「持續一段時間到現在」→ 現在完成式 has been。"},
{n:20,q:"I think you should accept the _____ and pay raise; after all, you earned them.",qz:"我覺得你應該接受升遷與加薪；畢竟這是你應得的。",o:["promoter","promotional","promote","promotion"],oz:["推動者","促銷的","晉升（動詞）","晉升（名詞）"],a:3,ex:"the 後接名詞，且與 pay raise 對等 → promotion（升遷）。promoter 是人，語意不合。"},
{n:21,q:"This coupon entitles you _____ one free cup of coffee.",qz:"憑這張優惠券，您可以免費兌換一杯咖啡。",o:["to","for","with","have"],oz:["到","為了","與","有"],a:0,ex:"entitle someone to something（使某人有權獲得某物）。"},
{n:22,q:"Greg seems very _____ from the project he's working on. He needs to take it easy.",qz:"葛雷格因為手上的專案看起來壓力很大。他需要放輕鬆一點。",o:["stressful","stressed","stressing","stress"],oz:["令人有壓力的","感到有壓力的","施壓中","壓力（名詞）"],a:1,ex:"人「感到」有壓力用 -ed：stressed。stressful 用來形容事情。"},
{n:23,q:"Oh cute! The master toymaker recreated the entire estate in _____.",qz:"好可愛！那位玩具大師把整座莊園做成了縮小模型。",o:["feature","amateur","miniature","caricature"],oz:["特色","業餘者","縮小模型","諷刺漫畫"],a:2,ex:"in miniature（以縮小版的形式），符合玩具師傅與 cute 的語境。"},
{n:24,q:"After _____ his newly given authority by being very rude to the other employees, Daniel has fallen from the boss's good graces.",qz:"在對其他員工非常無禮、濫用他新獲得的權力之後，丹尼爾已失去老闆的寵信。",o:["abuses","abusing","abused","was abusing"],oz:["濫用（第三人稱）","濫用（動名詞）","濫用（過去式）","正在濫用"],a:1,ex:"介系詞 After 後接動名詞 → abusing。"},
{n:25,q:"Our company is downsizing, so our manager has told us to prepare for the _____ scenario.",qz:"我們公司正在裁員縮編，所以經理要我們為最壞的情況做好準備。",o:["bad","worse","worst","badly"],oz:["壞的","更壞的","最壞的","糟糕地"],a:2,ex:"the worst scenario / worst-case scenario（最壞情況），the 搭配最高級。"},
{n:26,q:"The guests availed _____ of the free champagne at the exhibition opening.",qz:"賓客們在展覽開幕式上享用了免費的香檳。",o:["themselves","their","them","they"],oz:["他們自己","他們的","他們（受格）","他們（主格）"],a:0,ex:"固定用法 avail oneself of something（利用、享用某物），主詞 guests → themselves。"},
{n:27,q:"Because my professor understands that I have been very busy, he _____ extended the deadline on my research paper.",qz:"因為教授理解我一直很忙，他寬容地延長了我研究報告的截止日期。",o:["callously","mercifully","maliciously","frenetically"],oz:["冷酷地","仁慈地","惡意地","狂亂地"],a:1,ex:"教授體諒學生而延期，是善意的行為 → mercifully（仁慈地）。"},
{n:28,q:"Though my friend has a soft spot for older cinema, I prefer to watch more _____ films.",qz:"雖然我朋友偏愛老電影，但我比較喜歡看當代的電影。",o:["dated","recurrent","outmoded","contemporary"],oz:["過時的","反覆發生的","過時的","當代的"],a:3,ex:"Though 表對比：朋友喜歡 older cinema，我則喜歡 contemporary（當代的）電影。dated／outmoded 都是「過時的」。"},
{n:29,q:"_____ build customer loyalty, companies need to engage consumers on as many levels as possible.",qz:"為了建立顧客忠誠度，公司需要在盡可能多的層面與消費者互動。",o:["In order to","Instead of","As if","How"],oz:["為了","而不是","彷彿","如何"],a:0,ex:"空格後接原形動詞 build，表目的 → In order to。Instead of 後須接 V-ing。"},
{n:30,q:"The applicants for the marketing intern position come from _____ backgrounds and levels of experience.",qz:"應徵行銷實習職位的人來自各種不同的背景與經驗程度。",o:["variation","varying","varies","variable"],oz:["變化（名詞）","各不相同的","變化（動詞）","可變的"],a:1,ex:"修飾名詞 backgrounds 需形容詞；varying backgrounds（各式各樣的背景）是常見搭配。variable 指「易變的」，語意不合。"}
]},
{ part: 6, title: "Part 6｜Wanted: Supporting Actor",
passage: `<p><b>Wanted: Supporting Actor</b></p><p>We are looking for a male character actor to play the funny, but not __(31)__ best friend of the leading role in our upcoming film <i>Ah Geez I'm in Love</i>.</p><p>We want someone who looks friendly, but not __(32)__ . The person must also be wacky, but in a way that doesn't steal __(33)__ from the male lead. __(34)__</p>`,
pz: `<p><b>徵求：男配角</b></p><p>我們正在尋找一位男性性格演員，在即將上映的電影《天啊我戀愛了》中飾演主角那位有趣但不迷人的好朋友。</p><p>我們希望這個人看起來友善，但不具威脅感。他也必須古怪搞笑，但不能搶走男主角的風采。試鏡將於 11 月 14 日星期五上午 9 點至下午 3 點，在西格林斯伯勒路 284 號舉行。</p>`,
qs: [
{n:31,q:"Question 31",o:["fresh","female","attractive","geometric"],oz:["新鮮的","女性的","有吸引力的","幾何的"],a:2,ex:"配角是「有趣但不迷人」的好友，才不會蓋過主角 → attractive。female 與 male character actor 矛盾。"},
{n:32,q:"Question 32",o:["intimidating","intimidates","intimidated","intimidation"],oz:["令人畏懼的","威嚇（動詞）","感到害怕的","恐嚇（名詞）"],a:0,ex:"but not 與 friendly（形容詞）對等，需形容詞；形容人給別人的感覺用 -ing → intimidating。"},
{n:33,q:"Question 33",o:["time","ethics","money","attention"],oz:["時間","道德","金錢","注意力"],a:3,ex:"steal attention from（搶走…的鋒頭／注意力），符合配角不能搶戲的語意。"},
{n:34,q:"Question 34",o:["Auditions will be held from 9 a.m. to 3 p.m. on Friday, November 14, at 284 West Greensborough Road.","The woman should also be athletic and able to perform her own stunts if needed.","The film was well-reviewed overall, but did poorly because it was not shown in enough theaters.","Children must obtain permission from their parents before auditioning for the part."],oz:["試鏡將於 11 月 14 日週五上午 9 點至下午 3 點在西格林斯伯勒路 284 號舉行。","這位女性也應該擅長運動並能自己表演特技。","這部電影整體評價很好，但因上映戲院不足而票房不佳。","兒童試鏡前必須取得父母同意。"],a:0,ex:"徵人廣告結尾通常提供試鏡時間地點。(B) 女性與徵男演員矛盾；(C) 電影尚未上映；(D) 文中沒提到兒童。"}
]},
{ part: 6, title: "Part 6｜Dear Abby",
passage: `<p>Dear Abby,</p><p>Normally I don't write in to advice columns, but lately I feel I have no __(35)__ . I'm confused because there isn't really anything wrong __(36)__ my life.</p><p>__(37)__ I like my job and I like where I live, I still feel sad sometimes. __(38)__</p><p>Sincerely,<br>Anonymous</p>`,
pz: `<p>親愛的艾比：</p><p>我平常不會投書到諮詢專欄，但最近我覺得自己失去了方向。我很困惑，因為我的生活其實並沒有什麼問題。</p><p>雖然我喜歡我的工作，也喜歡我住的地方，但我有時還是會感到難過。有什麼辦法能改善我的心情嗎？</p><p>匿名者 敬上</p>`,
qs: [
{n:35,q:"Question 35",o:["service","nothing","direction","possibility"],oz:["服務","什麼都沒有","方向","可能性"],a:2,ex:"have no direction（沒有方向、迷失），符合後文「困惑」的語意。"},
{n:36,q:"Question 36",o:["up","onto","with","by"],oz:["向上","到…上","與","藉由"],a:2,ex:"固定搭配 something is wrong with…（…有問題）。"},
{n:37,q:"Question 37",o:["Although","Besides","For","Meanwhile"],oz:["雖然","除此之外","因為","同時"],a:0,ex:"喜歡工作和住處 vs. 還是難過 → 讓步 Although，且連接兩個子句。"},
{n:38,q:"Question 38",o:["Do you know of a better way to do it?","What time do you think I will get it back?","How can I share my happiness with others?","Can anything be done to improve my mood?"],oz:["你知道更好的做法嗎？","你覺得我幾點能拿回來？","我要怎麼和別人分享快樂？","有什麼辦法能改善我的心情嗎？"],a:3,ex:"寫信給諮詢專欄、說自己難過 → 結尾提出求助的問題：如何改善心情。"}
]},
{ part: 6, title: "Part 6｜Sarcopenia（肌少症）",
passage: `<p>When you are younger, your muscles grow larger and larger, but after about the age of 30, you will begin to lose muscle __(39)__ . This is __(40)__ a process called sarcopenia. Physically inactive people lose about 3 to 5 percent of their muscles every 10 years.</p><p>__(41)__ Unlike younger people, once elderly people lose muscles, they are unlikely to get them back. Exercise is the most common and __(42)__ treatment for sarcopenia.</p>`,
pz: `<p>年輕時，你的肌肉會越長越大，但大約 30 歲以後，你會開始流失肌肉量。這是由於一種稱為「肌少症」的過程。缺乏運動的人每 10 年會流失約 3% 到 5% 的肌肉。</p><p>到了大約 75 歲時，這個過程會加速。不同於年輕人，老年人一旦流失肌肉，就很難再長回來。運動是治療肌少症最常見也最有效的方法。</p>`,
qs: [
{n:39,q:"Question 39",o:["mass","stock","depth","quality"],oz:["量／質量","存貨","深度","品質"],a:0,ex:"muscle mass（肌肉量）為固定搭配。"},
{n:40,q:"Question 40",o:["in addition to","in contrast to","instead of","due to"],oz:["除了…之外","與…相反","而不是","由於"],a:3,ex:"肌肉流失「是因為」肌少症這個過程 → due to。"},
{n:41,q:"Question 41",o:["It continues to accumulate even after symptoms appear.","Quick treatment of this illness is the best cure.","By the time you are about 75, this process quickens.","After infecting a person, it can be quickly spread to others."],oz:["即使症狀出現後它仍持續累積。","快速治療是最好的療法。","到了大約 75 歲，這個過程會加速。","感染一個人後，它會很快傳給別人。"],a:2,ex:"前文講年齡與肌肉流失速度，後文接 elderly people，所以接「75 歲時加速」最連貫。肌少症不會傳染，(D) 錯。"},
{n:42,q:"Question 42",o:["affected","effectively","effect","effective"],oz:["受影響的","有效地","效果（名詞）","有效的"],a:3,ex:"與 common 對等、修飾名詞 treatment → 形容詞 effective。"}
]},
{ part: 6, title: "Part 6｜Santa Claus",
passage: `<p>The __(43)__ inspiration for Santa Claus was Saint Nicholas, who was born around the end of the third century C.E. St. Nicholas inspired many legends and folktales, and it __(44)__ that he gave away all the wealth he inherited and traveled around, aiding the ill and the impoverished.</p><p>Saint Nicholas was a popular figure in Europe for centuries, and he was first __(45)__ into American culture when a group of Dutch families gathered to honor him. Nicholas's Dutch nickname was Sinter Klaas. __(46)__</p>`,
pz: `<p>聖誕老人在歷史上的原型是聖尼古拉，他大約出生於西元三世紀末。聖尼古拉啟發了許多傳說與民間故事，據信他把繼承的財富全數捐出，四處遊歷，幫助病人與窮人。</p><p>聖尼古拉在歐洲受人愛戴長達數世紀，而他首次被融入美國文化，是當一群荷蘭家庭聚集起來紀念他的時候。尼古拉的荷蘭暱稱是 Sinter Klaas，這個名字最終演變成英語化的 Santa Claus。</p>`,
qs: [
{n:43,q:"Question 43",o:["ghostly","musical","fictional","historical"],oz:["鬼魂般的","音樂的","虛構的","歷史上的"],a:3,ex:"聖尼古拉是真實存在的歷史人物（有出生年代）→ historical inspiration。"},
{n:44,q:"Question 44",o:["belief","believed","believes","is believed"],oz:["信念（名詞）","相信（過去式）","相信（第三人稱）","被認為"],a:3,ex:"虛主詞句型 It is believed that…（據信…）。"},
{n:45,q:"Question 45",o:["incorporated","incorporating","incorporation","to incorporate"],oz:["被納入","納入中","合併（名詞）","去納入"],a:0,ex:"he was first ___ into → 被動語態 was + p.p.：was incorporated into（被融入）。"},
{n:46,q:"Question 46",o:["Saint Nicholas was born in the village of Patara, an area which is now part of Turkey.","This eventually evolved into the anglicized Santa Claus.","Santa Claus is a legendary figure of Western Christian culture.","According to tradition, Santa Claus brings gifts to well-behaved children on Christmas Eve."],oz:["聖尼古拉出生於帕塔拉村，現屬土耳其。","這個名字最終演變成英語化的 Santa Claus。","聖誕老人是西方基督教文化中的傳奇人物。","根據傳統，聖誕老人會在平安夜送禮物給乖孩子。"],a:1,ex:"前一句剛講荷蘭暱稱 Sinter Klaas，This 指這個名字，接「演變成 Santa Claus」最自然。"}
]},
{ part: 7, title: "Part 7｜管理團隊的訊息討論",
passage: `<p><b>Doris May (18:56 Saturday, April 6)</b><br>I need some advice on managing my team. No matter what project I give them, they seem to have a lot of difficulty finishing it on time. What can I do?</p><p><b>Susan Reynolds (10:01 Sunday, April 7)</b><br>It sounds like you're not giving them enough structure. Break the project into smaller pieces.</p><p><b>Mike Hays (13:15 Sunday, April 7)</b><br>I agree with Susan. I'd also add that you should make sure you avoid leaving larger tasks towards the end. Your team will run out of time.</p><p><b>Doris May (14:07 Sunday, April 7)</b><br>@Mike I hear you. How do I set hard limits without babysitting them?</p><p><b>Patricia Wells (18:54 Sunday, April 7)</b><br>@Doris Some employees will underperform no matter what. I would suggest praising/rewarding the most productive team member. Soon others will follow suit.</p><p><b>Doris May (19:17 Sunday, April 7)</b><br>@Patricia Great, thanks!</p>`,
pz: `<p><b>桃樂絲・梅（4/6 週六 18:56）</b><br>我需要一些管理團隊的建議。不管我給他們什麼專案，他們似乎都很難準時完成。我該怎麼辦？</p><p><b>蘇珊・雷諾茲（4/7 週日 10:01）</b><br>聽起來你沒有給他們足夠的架構。把專案拆成較小的部分。</p><p><b>麥克・海斯（4/7 週日 13:15）</b><br>我同意蘇珊。我還要補充，你應確保不要把較大的任務留到最後，不然你的團隊會來不及。</p><p><b>桃樂絲・梅（4/7 週日 14:07）</b><br>@麥克 我懂你的意思。我要怎麼設定硬性期限，又不用像保母一樣盯著他們？</p><p><b>派翠西亞・威爾斯（4/7 週日 18:54）</b><br>@桃樂絲 有些員工不管怎樣都會表現不佳。我建議稱讚／獎勵最有生產力的成員，很快其他人就會跟進。</p><p><b>桃樂絲・梅（4/7 週日 19:17）</b><br>@派翠西亞 太好了，謝謝！</p>`,
qs: [
{n:47,q:"What is implied about Doris May?",qz:"關於桃樂絲・梅，文中暗示了什麼？",o:["She is not fit to be a manager.","No one likes her.","She is new to managing.","Her projects are very difficult."],oz:["她不適合當主管。","沒有人喜歡她。","她是管理新手。","她的專案非常困難。"],a:2,ex:"她向別人請教基本的管理方法（如何拆分任務、設定期限），暗示她剛開始當主管。其他選項文中沒有依據。"},
{n:48,q:"On April 7 at 14:07, what does Doris May mean when she writes, \"I hear you\"?",qz:"4 月 7 日 14:07，桃樂絲寫「I hear you」是什麼意思？",o:["She received a voice mail.","She understands.","She disagrees.","She wants them to explain further."],oz:["她收到語音留言。","她明白了。","她不同意。","她希望他們進一步解釋。"],a:1,ex:"I hear you 是口語「我懂你的意思／了解」，不是字面上的「聽到」。"}
]},
{ part: 7, title: "Part 7｜Banana Walnut Muffins 食譜",
passage: `<p><b>Mrs. Kendra Lipnisky's Banana Walnut Muffins</b></p><p>2 eggs<br>1/2 cup of butter, softened<br>1 and 1/2 cups of brown sugar<br>4 tablespoons of buttermilk<br>1 teaspoon of baking soda<br>1 teaspoon of vanilla extract<br>1 and 1/2 cups of flour (preferably sifted)<br>2 bananas, mashed<br>1 cup of walnuts or any other nut you like (break into larger chunks)</p><p><b>Baking Directions</b><br>1. Preheat oven to 350°F (175°C).<br>2. Grease muffin tin.<br>3. Cream the butter and sugar.<br>4. Add buttermilk, blend, and then mix in the eggs followed by the mashed banana.<br>5. Add flour and baking soda, stir to combine.<br>6. Stir in walnut chunks.<br>7. Pour batter into muffin tin until each mold is about 2/3 full.<br>8. Bake at 350°F for 20-25 minutes, or until tops are brown.<br>9. Additionally, a toothpick may be inserted into the center of the muffin as a test. If it comes out cleanly, then the muffins are done.</p><p>Nutritional Info (per muffin): Calories-238; Fat-11g; Carbs-32g; Fiber-1g; Protein-3g</p>`,
pz: `<p><b>肯卓拉・李普尼斯基太太的香蕉核桃馬芬</b></p><p>雞蛋 2 顆<br>軟化奶油 1/2 杯<br>紅糖 1 又 1/2 杯<br>白脫牛奶 4 大匙<br>小蘇打 1 小匙<br>香草精 1 小匙<br>麵粉 1 又 1/2 杯（最好過篩）<br>香蕉 2 根，壓成泥<br>核桃或任何你喜歡的堅果 1 杯（掰成較大塊）</p><p><b>烘焙步驟</b><br>1. 烤箱預熱至 350°F（175°C）。<br>2. 在馬芬模具上抹油。<br>3. 將奶油和糖打發。<br>4. 加入白脫牛奶攪拌，再拌入雞蛋，接著加入香蕉泥。<br>5. 加入麵粉和小蘇打，攪拌均勻。<br>6. 拌入核桃塊。<br>7. 將麵糊倒入模具，每格約 2/3 滿。<br>8. 以 350°F 烤 20–25 分鐘，或直到表面呈金黃色。<br>9. 另外，可將牙籤插入馬芬中心測試，若拔出時乾淨無沾黏，就表示烤好了。</p><p>營養成分（每個）：熱量 238；脂肪 11g；碳水 32g；纖維 1g；蛋白質 3g</p>`,
qs: [
{n:49,q:"What is one method the recipe does NOT suggest could be used to check if the muffins are done?",qz:"下列哪一個方法是食譜「沒有」建議用來檢查馬芬是否烤好的？",o:["Considering the total baking time","Poking the muffin with a toothpick","Looking at the color of the muffin top","Touching the muffin to see if it's soft"],oz:["考慮總烘烤時間","用牙籤戳馬芬","看馬芬頂部的顏色","摸馬芬看是否鬆軟"],a:3,ex:"步驟 8 提到時間（20–25 分鐘）與表面變褐色，步驟 9 提到牙籤；「用手摸」沒有提到。"},
{n:50,q:"Which of the following ingredient substitutions would NOT ruin the recipe?",qz:"下列哪一種食材替換「不會」毀掉這份食譜？",o:["Adding salt instead of sugar","Adding olive oil instead of butter","Adding icing sugar instead of flour","Adding peanuts instead of walnuts"],oz:["用鹽取代糖","用橄欖油取代奶油","用糖粉取代麵粉","用花生取代核桃"],a:3,ex:"食材寫 walnuts or any other nut you like（核桃或任何喜歡的堅果），所以換成花生沒問題。"}
]},
{ part: 7, title: "Part 7｜Bowmonte 小型企業講座",
passage: `<p><b>Seminars on Small Business Available at Bowmonte City Hall</b><br>Originally Posted: 11/15 11:54:44 PM MDT | Updated: 5 Hours Ago</p><p>Tomorrow marks the first anniversary of the Bowmonte City Business Association's continuing series of free small business seminars. The city is pleased to announce the return of its series of workshops aimed at small business owners or anyone who wishes to start their own company in Bowmonte. The workshops will occur on the third Wednesday of each month. The first will be hosted tomorrow on Nov. 21 at city hall and is scheduled to feature numerous success stories about local businesses, as told by their founders, managers, and innovating employees.</p><p>Each free session will begin at 7 p.m. and go until 9 p.m. The sessions are generated in collaboration with the Bowmonte Financial Expansion Partnership and "Business Besties," a networking group based in Bowmonte.</p><p>Can't make it in person? This year, we are also pleased to offer the "webinar" option. We will be streaming the seminars with an integrated chat function where viewers may post their questions during the Q&amp;A section of the seminar in real time. To join, simply visit: <u>bowmontecityhall.com/live</u><br>Unlike last year, this wave of seminars will be recorded, so you can check out our online database and review previous seminars at: <u>bowmontecityhall.com/seminars/archives</u></p><p>Registration is not required.</p>`,
pz: `<p><b>Bowmonte 市政廳開辦小型企業講座</b><br>首次發布：11/15 晚上 11:54:44（山區時間）｜更新於 5 小時前</p><p>明天是 Bowmonte 市商業協會免費小型企業系列講座的一週年。市府很高興宣布，這系列針對小型企業主、或任何想在 Bowmonte 創業者的工作坊將再度開辦。工作坊將於每月第三個星期三舉行。第一場將於明天 11 月 21 日在市政廳舉辦，預定分享許多在地企業的成功故事，由創辦人、經理及創新員工親自講述。</p><p>每場免費講座從晚上 7 點到 9 點。講座是與 Bowmonte 財務擴展合作組織以及在地人脈社團「Business Besties」合作舉辦。</p><p>無法親自到場嗎？今年我們也很高興提供「線上研討會」選項。我們將直播講座，並內建聊天功能，讓觀眾能在問答時段即時發問。只要前往 bowmontecityhall.com/live 即可參加。<br>與去年不同，本系列講座將會錄影，你可以到我們的線上資料庫 bowmontecityhall.com/seminars/archives 觀看先前的講座。</p><p>不需報名。</p>`,
qs: [
{n:51,q:"What can be assumed about this online advertisement?",qz:"關於這則線上廣告，可以推斷出什麼？",o:["There is not much interest in the seminars.","There was not an online option last year.","It is intended for people living outside of Bowmonte.","It advises that those interested in the seminars make reservations."],oz:["大家對講座興趣不大。","去年沒有線上選項。","它是寫給住在 Bowmonte 以外的人。","它建議有興趣的人先預約。"],a:1,ex:"「This year, we are also pleased to offer the 'webinar' option」→ 今年才有線上選項，可推知去年沒有。文中明說不需報名，(D) 錯。"},
{n:52,q:"How can people watch last year's seminars?",qz:"人們要如何觀看去年的講座？",o:["Go to bowmontecityhall.com/live to access them","Go to bowmontecityhall.com/seminars/archives to access them","Go to the Bowmonte city hall and request the recordings","None of the above"],oz:["到 /live 網址觀看","到 /seminars/archives 網址觀看","到市政廳索取錄影","以上皆非"],a:3,ex:"「Unlike last year, this wave of seminars will be recorded」→ 去年的講座沒有錄影，所以無法觀看。陷阱：archives 是今年起的錄影。"}
]},
{ part: 7, title: "Part 7｜Carmen's Cupcakes 訂購單",
passage: `<p><b>Carmen's Cupcakes Order Form</b></p><p>Order Number: MDC – 2085<br>Full Name: Fielder (First name) Wright (Last name)<br>Birth Date: 11 (Month) / 16 (Day) / 1992 (Year)<br>E-mail: f.wright@crestwalkfoundation.com<br>Mobile / Phone Number: 01-555-222-5258</p><p><b>Cupcake Flavors (2 dozen minimum)</b><br>Vanilla: 2<br>Chocolate: 10<br>Coconut: 0<br>Carrot Cake: 5<br>Peanut Butter: 2</p><p><b>Icing (Optional):</b><br>Coconut: 5<br>Peanut Butter: 12<br>Cream Cheese: 1<br>Dark Chocolate: 1<br>Milk Chocolate: 0<br>Strawberry: 0<br>Mint: 0</p><p>Pickup Date/Time: 10 (Month) / 30 (Day) / 2016 (Year)　11 : 30 A.M. / P.M.</p><p>Special Details: Though peanuts are fine, please ensure that no almonds or cashews are added to the cupcakes</p><p>Note: Cancellation of orders within 48 hours of the pickup date will still result in the customer being charged the full amount.</p>`,
pz: `<p><b>Carmen's 杯子蛋糕訂購單</b></p><p>訂單編號：MDC–2085<br>姓名：Fielder Wright<br>生日：1992 年 11 月 16 日<br>電子郵件：f.wright@crestwalkfoundation.com<br>手機／電話：01-555-222-5258</p><p><b>杯子蛋糕口味（最少 2 打）</b><br>香草：2<br>巧克力：10<br>椰子：0<br>紅蘿蔔蛋糕：5<br>花生醬：2</p><p><b>糖霜（可選）：</b><br>椰子：5<br>花生醬：12<br>奶油起司：1<br>黑巧克力：1<br>牛奶巧克力：0<br>草莓：0<br>薄荷：0</p><p>取貨日期／時間：2016 年 10 月 30 日 11:30</p><p>特殊說明：花生沒問題，但請確保杯子蛋糕裡不要加杏仁或腰果。</p><p>注意：於取貨日前 48 小時內取消訂單，仍需支付全額。</p>`,
qs: [
{n:53,q:"What can be assumed about Fielder Wright?",qz:"關於 Fielder Wright 可以推斷出什麼？",o:["He is not a legal adult.","\"Fielder Wright\" is his pen name.","He will eat all of these cupcakes himself.","He or someone he knows has a nut allergy."],oz:["他還未成年。","「Fielder Wright」是他的筆名。","他會自己吃掉所有杯子蛋糕。","他或他認識的人對堅果過敏。"],a:3,ex:"特殊說明特別要求不要加杏仁或腰果 → 推測有人對這些堅果過敏。他 1992 年生，已成年。"},
{n:54,q:"What will Fielder likely have to do before his order will be filled?",qz:"在訂單被處理前，Fielder 可能必須做什麼？",o:["He'll have to buy more cupcakes.","He'll have to change the icing types.","He'll have to change the pickup time.","He'll have to provide more personal information."],oz:["他必須買更多杯子蛋糕。","他必須更改糖霜種類。","他必須更改取貨時間。","他必須提供更多個人資料。"],a:0,ex:"最低訂購量 2 打＝24 個，但他只訂了 2+10+0+5+2＝19 個，不足，所以得加訂。"}
]},
{ part: 7, title: "Part 7｜章魚 The Octopus",
passage: `<p>The octopus (in any form of subspecies) is a fascinating creature. —[1]— It's common knowledge that it has eight tentacles — hence the "octo" prefix in its name — but it also has three hearts, a beak, venom, ink which it can excrete for defense, and no bones. Being boneless allows the octopus to squeeze into incredibly small spaces. —[2]— The octopus can also propel itself by taking in and expelling water from its body. It can even regenerate lost limbs. But perhaps most impressively, the octopus possesses far and away the most rapid physical camouflage ability of any animal in the world. —[3]— The octopus is also believed to be the most intelligent of all invertebrate creatures, demonstrating short-term and long-term memory as well as complex directional and problem solving skills. Many who study octopuses assert that they also play, use tools, learn lessons from experience, and are capable of distinguishing between people. Octopuses even show preference, swimming up to people they like and squirting ink or water at people they don't. —[4]—</p>`,
pz: `<p>章魚（無論哪一亞種）都是迷人的生物。—[1]— 大家都知道牠有八隻觸手——所以名字有「octo（八）」的字首——但牠還有三顆心臟、一個喙、毒液、能排出用於防禦的墨汁，而且沒有骨頭。沒有骨頭讓章魚能擠進極小的空間。—[2]— 章魚也能藉由吸入並排出體內的水來推動自己前進。牠甚至能再生失去的觸手。但或許最令人驚嘆的是，章魚擁有全世界動物中遠遠最快速的身體偽裝能力。—[3]— 這種生物能瞬間改變顏色以配合複雜的圖案，或嚇跑掠食者。章魚也被認為是所有無脊椎動物中最聰明的，展現出短期與長期記憶，以及複雜的方向感與解決問題的能力。許多研究章魚的人主張，牠們也會玩耍、使用工具、從經驗中學習，並能分辨不同的人。章魚甚至會表現出好惡，游向牠們喜歡的人，對不喜歡的人噴墨汁或水。—[4]—</p>`,
qs: [
{n:55,q:"What is NOT something the article implies an octopus is capable of doing?",qz:"下列何者「不是」文章暗示章魚能做到的事？",o:["Befriending a human","Navigating through a maze","Regenerating broken bones","Blending in with its surroundings"],oz:["和人類交朋友","穿越迷宮","再生斷掉的骨頭","融入周遭環境"],a:2,ex:"章魚「沒有骨頭（no bones）」，所以不可能再生骨頭；文中說的是再生 limbs（肢體）。"},
{n:56,q:"Based on the article, which of the following is true about octopuses?",qz:"根據文章，關於章魚下列何者正確？",o:["They have multiple hearts.","They have a very long life span.","They have not been studied by humans.","They are the least intelligent invertebrate animals."],oz:["牠們有多顆心臟。","牠們壽命很長。","人類沒有研究過牠們。","牠們是最不聰明的無脊椎動物。"],a:0,ex:"文中寫 it also has three hearts → 有多顆心臟。(D) 剛好相反，是最聰明的。"},
{n:57,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"The creature is capable of instantly changing its color to match complex pattern or scare away predators.\"",qz:"下列句子最適合放在 [1]、[2]、[3]、[4] 哪個位置？\n「這種生物能瞬間改變顏色以配合複雜的圖案或嚇跑掠食者。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:2,ex:"[3] 前一句剛講「最快速的身體偽裝能力（camouflage）」，接著說明能瞬間變色，語意最連貫。"}
]},
{ part: 7, title: "Part 7｜課程意見調查表",
passage: `<p>Date (m/d/y): June 16, 2016<br>Class: Entrepreneurship 101</p><p>1. How would you rate this class? (1–5) → <b>4</b><br>Why?<br><u>Although I learned a lot, I feel that I could have studied more in the amount of time given, or the same amount in less time.</u></p><p>2. How would you rate your professor? (1–5) → <b>4</b><br>Why?<br><u>Though knowledgeable, he spoke too quietly, and sometimes he was late to class.</u></p><p>3. What did you like best about the class?<br><u>The hands-on work where we were given problems to solve in the field was very informative.</u></p><p>4. What do you feel needs to be improved?<br><u>Some of the lectures were based only on theory and so did not seem relevant to the real world. As a result, I had trouble remembering what was taught.</u></p><p>5. Additional comments or suggestions?<br><u>I'd really prefer fewer lectures and less theory-based reading. If the course could have more hands-on projects, that would be great.</u></p>`,
pz: `<p>日期：2016 年 6 月 16 日<br>課程：創業學 101</p><p>1. 你會給這門課打幾分？（1–5）→ <b>4</b><br>原因：雖然我學到很多，但我覺得在給定的時間內本可以學得更多，或用更少時間學到同樣的量。</p><p>2. 你會給教授打幾分？（1–5）→ <b>4</b><br>原因：教授雖然學識淵博，但說話太小聲，有時還會遲到。</p><p>3. 你最喜歡這門課的哪一點？<br>在現場解決實際問題的實作練習非常有收穫。</p><p>4. 你覺得什麼需要改進？<br>有些課只講理論，似乎與現實世界無關。因此我很難記住教過的內容。</p><p>5. 其他意見或建議？<br>我真的比較希望少一點講課、少一點理論性閱讀。如果課程能有更多實作專題就太好了。</p>`,
qs: [
{n:58,q:"What is most likely to be the student's learning style?",qz:"這位學生最可能是哪一種學習風格？",o:["Visual","Kinesthetic","Auditory","Negative"],oz:["視覺型","動覺（實作）型","聽覺型","負面型"],a:1,ex:"學生最喜歡 hands-on work（動手實作），希望有更多 hands-on projects → 動覺型學習者。"},
{n:59,q:"How does the student seem to feel about theory-based learning?",qz:"學生對理論型學習似乎有什麼看法？",o:["It has little practical application.","Being abstract, it is easy to remember.","It is necessary for learning real-world skills.","None of the above"],oz:["它沒什麼實際用途。","因為抽象，所以容易記。","它對學習現實技能是必要的。","以上皆非"],a:0,ex:"「based only on theory and so did not seem relevant to the real world」→ 與現實脫節、缺乏實用性。他也說很難記住，(B) 錯。"},
{n:60,q:"What best summarizes the student's feelings towards the class?",qz:"下列何者最能總結學生對這門課的感受？",o:["Mostly satisfied but still critical","Mostly unsatisfied but still hopeful","Extremely angry because the professor was sometimes late","Completely unsatisfied because the class was a waste of time"],oz:["大致滿意但仍有批評","大致不滿意但仍抱有希望","因教授有時遲到而非常生氣","完全不滿意，覺得浪費時間"],a:0,ex:"課程與教授都給 4 分（滿分 5）→ 大致滿意，但也提出改進建議 → 仍有批評。"}
]},
{ part: 7, title: "Part 7｜巴西總統遭彈劾",
passage: `<p>On August 31, 2016, Brazil's first female president, Dilma Rousseff, was impeached for allegedly manipulating funds within the federal budget. This is also the first time in nearly 30 years that a democratically elected president has been ousted by the Brazilian Congress. According to supporters of the impeachment, Rousseff was moving money to fill gaps in the deficits of social programs to create the illusion of their success and help her win re-election. Her supporters deny these charges and claim that it is merely a scheme led by Eduardo Cunha, whom they call a political opportunist. Cunha himself was forced to resign in July due to allegations of corruption, an accusation which he denies. With Rousseff's approval rating dropping to 10 percent, it is unsurprising that many Brazilians support the congressional decision to remove her, stating that they are fed up with government corruption. However, like Cunha, many of the politicians who voted to impeach Rousseff are themselves presently under investigation for corruption charges.</p>`,
pz: `<p>2016 年 8 月 31 日，巴西首位女總統迪爾瑪・羅賽夫因涉嫌操弄聯邦預算資金而遭到彈劾。這也是近 30 年來，首次有民選總統被巴西國會趕下台。根據支持彈劾者的說法，羅賽夫挪用資金來填補社會福利計畫的赤字缺口，製造計畫成功的假象，以幫助自己連任。她的支持者否認這些指控，並聲稱這只是愛德華多・庫尼亞主導的陰謀，他們稱庫尼亞是個政治投機者。庫尼亞本人也在 7 月因貪腐指控被迫辭職，但他否認此指控。隨著羅賽夫的支持度降到 10%，許多巴西人支持國會將她撤職的決定也就不足為奇，他們表示已經受夠了政府貪腐。然而，和庫尼亞一樣，許多投票彈劾羅賽夫的政治人物本身目前也正因貪腐指控而接受調查。</p>`,
qs: [
{n:61,q:"Who removed Rousseff from office?",qz:"是誰將羅賽夫撤職的？",o:["Eduardo Cunha","The Brazilian media","The Brazilian Congress","The Brazilian voting public"],oz:["愛德華多・庫尼亞","巴西媒體","巴西國會","巴西選民"],a:2,ex:"「ousted by the Brazilian Congress」及「the congressional decision to remove her」→ 國會。"},
{n:62,q:"According to this article, what is something Cunha's opponents accuse him of?",qz:"根據文章，庫尼亞的反對者指控他什麼？",o:["Being a chauvinist","Unethically taking advantage of a situation","Moving funds to fill deficits","Winning the presidency illegally"],oz:["是沙文主義者","不道德地利用局勢","挪用資金填補赤字","非法贏得總統大位"],a:1,ex:"羅賽夫的支持者稱庫尼亞為 political opportunist（政治投機者）＝不道德地趁機圖利。(C) 是羅賽夫被指控的事。"},
{n:63,q:"According to this article, what can be assumed about Rousseff?",qz:"根據文章，關於羅賽夫可以推斷出什麼？",o:["She is currently unpopular in her own country.","She has definitely been proven guilty of corruption.","She has been unjustly removed because of her gender.","She has been ousted by the public for political reasons."],oz:["她目前在國內不受歡迎。","她已被確定證實貪腐有罪。","她因性別而被不公平地撤職。","她因政治因素被民眾趕下台。"],a:0,ex:"支持度只剩 10% → 不受歡迎。文中只說 allegedly（涉嫌），並未證實有罪。"},
{n:64,q:"According to this article, what is implied to be an underlying problem within Brazilian politics?",qz:"根據文章，暗示巴西政治的根本問題是什麼？",o:["Frequent impeachment","Widespread corruption","An ineffective voting system","Misinterpretation of the majority's wishes"],oz:["頻繁的彈劾","普遍的貪腐","無效的投票制度","誤解多數人的意願"],a:1,ex:"人民受夠政府貪腐，且投票彈劾的政治人物本身也在接受貪腐調查 → 貪腐普遍。近 30 年才第一次彈劾，(A) 錯。"}
]},
{ part: 7, title: "Part 7｜專案說明的群組訊息",
passage: `<p><b>M. Borton [10:21 p.m.]</b> Hey, do any of you guys have the project guidelines with you?</p><p><b>Andy T. [10:26 p.m.]</b> Nope.</p><p><b>Booker [10:26 p.m.]</b> Sorry, I don't.</p><p><b>M. Borton [10:31 p.m.]</b> Chiang, do you?</p><p><b>Chiang [10:34 p.m.]</b> I don't either.</p><p><b>M. Borton [10:34 p.m.]</b> What am I going to do? I can't do the project without the guidelines!</p><p><b>Chiang [10:37 p.m.]</b> Why don't you just stop by Peter's office tomorrow morning?</p><p><b>M. Borton [10:37 p.m.]</b> No way! That guy is terrifying. He'll probably yell at me for not writing down the guidelines.</p><p><b>Chiang [10:38 p.m.]</b> He's not as bad as you think he is. His bark is way worse than his bite.</p><p><b>M. Borton [10:39 p.m.]</b> Are you sure about that? Didn't you see how he reacted when Alex missed his deadline?</p><p><b>Chiang [10:42 p.m.]</b> Yeah, I did. But, to be fair, employees shouldn't miss their deadlines.</p>`,
pz: `<p><b>M. Borton [晚上 10:21]</b> 嘿，你們有人手上有專案說明嗎？</p><p><b>Andy T. [10:26]</b> 沒有。</p><p><b>Booker [10:26]</b> 抱歉，我沒有。</p><p><b>M. Borton [10:31]</b> Chiang，你有嗎？</p><p><b>Chiang [10:34]</b> 我也沒有。</p><p><b>M. Borton [10:34]</b> 我該怎麼辦？沒有說明我沒辦法做專案！</p><p><b>Chiang [10:37]</b> 你明天早上去 Peter 的辦公室問一下就好啦？</p><p><b>M. Borton [10:37]</b> 才不要！那個人很可怕。他大概會因為我沒把說明記下來而罵我。</p><p><b>Chiang [10:38]</b> 他沒有你想的那麼糟。他只是嘴巴兇，其實不會怎樣。</p><p><b>M. Borton [10:39]</b> 你確定嗎？你沒看到 Alex 錯過截止期限時他是什麼反應嗎？</p><p><b>Chiang [10:42]</b> 有，我看到了。但說句公道話，員工本來就不該錯過截止期限。</p>`,
qs: [
{n:65,q:"Who or what most likely are the speakers?",qz:"這些對話者最可能是什麼身分？",o:["Office workers","University students","High school students","Members of a family"],oz:["上班族","大學生","高中生","家人"],a:0,ex:"Peter's office、employees shouldn't miss their deadlines → 是公司同事（上班族）。"},
{n:66,q:"Based on the conversation, what is M. Borton afraid to do?",qz:"根據對話，M. Borton 害怕做什麼？",o:["Quit his job","Go to work in the morning","Ask his friend about a project","Ask his boss about the guidelines"],oz:["辭職","早上去上班","問朋友專案的事","向老闆詢問專案說明"],a:3,ex:"Chiang 建議他去 Peter 的辦公室問，他說 That guy is terrifying → 害怕去問老闆。"},
{n:67,q:"At 10:39 p.m., what does M. Borton imply when he writes, \"Didn't you see how he reacted when Alex missed his deadline\"?",qz:"10:39 時，M. Borton 寫「你沒看到 Alex 錯過截止期限時他的反應嗎」暗示什麼？",o:["Peter got angry at an employee.","Chiang doesn't pay attention at work.","M. Borton wants to know how Peter reacted.","M. Borton wasn't sure if his colleagues were at work."],oz:["Peter 曾對一位員工發脾氣。","Chiang 上班不專心。","M. Borton 想知道 Peter 的反應。","M. Borton 不確定同事是否在上班。"],a:0,ex:"他用這句反駁「Peter 沒那麼兇」，暗示 Peter 曾因 Alex 遲交而大發脾氣。"}
]},
{ part: 7, title: "Part 7｜Peaceful Valley Retreat 課程",
passage: `<p><b>Registration for Peaceful Valley Retreat Relaxation Courses Now Open</b></p><p>Do you feel like there is a vise tightening around your head? Does work have you down? Then you need to unplug and unwind at the Peaceful Valley Retreat. Come just for a week-long course or stay for the whole month; at Peaceful Valley Retreat you do what's right for you. The courses offered are as follows:</p><p>Centering the Mind: (November 1-8 / 10 a.m. to 3 p.m.). In this course you center your mind and learn how to be at peace with yourself and the world around you. You will study visualization, proper breathing techniques, inward focus, and greater mental awareness.<br>Cost NT$6,000.</p><p>Two Weeks of Yoga: (November 9-23 / 9 a.m. to 12 p.m., 4 p.m. to 7 p.m.). Treat your mind and body to 14 days of mental relaxation and gentle strengthening exercises. Yoga can steady your mental facilities, relieve stress, and tone the entire body. Work through your stress issues while you simultaneously work out sore muscles and knots.<br>Cost NT$15,000.</p><p>Reconnect with Nature: (November 24-31 / all day). Reconnect with nature by going on a one-week hiking and camping trip. "Reconnect with Nature" combines the previous two courses by starting each day with meditation followed by yoga to ensure you are centered and limber before undertaking day-long hikes through Peaceful Valley. Each night before resting, you'll learn how to detoxify by preparing simple and healthy vegan meals using ingredients harvested from our organic farms and among the local flora.<br>Cost NT$16,000.</p><p>For additional information, please contact Ben Mayur at 09-976-455-128 or <u>relaxingwithben@yahoo.com</u>.</p><p>We are only accessible by ferry. The Cowichan Bay Harbor is located just off of Highway 5A. Ferries to Peaceful Valley depart at 7 a.m., 9 a.m., and 11 a.m. every day.</p>`,
pz: `<p><b>Peaceful Valley 靜修所放鬆課程開放報名</b></p><p>你是否覺得頭像被老虎鉗夾緊？工作讓你心情低落嗎？那你需要來 Peaceful Valley 靜修所斷線、放鬆一下。可以只來上一週的課程，也可以待上一整個月；在這裡，你做最適合自己的事。課程如下：</p><p>「心靈歸中」（11 月 1–8 日／上午 10 點至下午 3 點）：在這門課中你將讓心靈沉澱，學習如何與自己和周遭世界和平共處。你將學習觀想、正確的呼吸技巧、向內專注以及提升心智覺察。<br>費用新台幣 6,000 元。</p><p>「兩週瑜伽」（11 月 9–23 日／上午 9 點至 12 點、下午 4 點至 7 點）：給身心 14 天的心靈放鬆與溫和的肌力訓練。瑜伽能穩定心智、紓解壓力、雕塑全身。在處理壓力問題的同時，也舒緩痠痛的肌肉與結節。<br>費用新台幣 15,000 元。</p><p>「重返自然」（11 月 24–31 日／全天）：參加為期一週的健行露營，重新與自然連結。此課程結合前兩門課，每天以冥想開始、接著做瑜伽，確保你身心集中且柔軟，再展開穿越 Peaceful Valley 的全天健行。每晚休息前，你將學習用我們有機農場與當地植物採收的食材，準備簡單健康的純素餐點來排毒。<br>費用新台幣 16,000 元。</p><p>如需更多資訊，請聯絡 Ben Mayur：09-976-455-128 或 relaxingwithben@yahoo.com。</p><p>我們只能搭渡輪抵達。Cowichan Bay 港位於 5A 號公路旁。前往 Peaceful Valley 的渡輪每天上午 7 點、9 點及 11 點出發。</p>`,
qs: [
{n:68,q:"How much would it cost for someone to attend all three courses?",qz:"參加全部三門課程要花多少錢？",o:["NT$16,000","NT$21,000","NT$37,000","NT$48,000"],oz:["16,000 元","21,000 元","37,000 元","48,000 元"],a:2,ex:"6,000 + 15,000 + 16,000 = 37,000。"},
{n:69,q:"What will the healthy vegan meals prepared in the \"Reconnect with Nature\" course likely contain?",qz:"「重返自然」課程準備的健康純素餐點可能包含什麼？",o:["Organic fruits, vegetables, and grains","Organic cheeses, eggs, fruits, and vegetables","\"Happy-cow\" milk and gluten-free carbohydrates","Humanely slaughtered chicken and organic vegetables"],oz:["有機水果、蔬菜和穀物","有機起司、蛋、水果和蔬菜","「快樂牛」牛奶與無麩質碳水","人道屠宰的雞肉與有機蔬菜"],a:0,ex:"vegan（純素）不吃任何動物製品，起司、蛋、牛奶、雞肉都不行 → 只有 (A)。"},
{n:70,q:"Which most closely describes the goals of the courses offered at this retreat?",qz:"下列何者最接近這個靜修所課程的目標？",o:["To stretch, exercise, sweat, and gain weight","To overcome doubt, adversity, evil, and spiritual imbalance","To remove wind, technology, and poison from the center of the body","To relax, stop using technology, eat a healthy diet, and gain mental and emotional focus"],oz:["伸展、運動、流汗、增重","克服懷疑、逆境、邪惡與靈性失衡","從身體中心排除風、科技與毒素","放鬆、停用科技、健康飲食、獲得心理與情緒的專注"],a:3,ex:"unplug and unwind（斷線、放鬆）、健康純素餐、center your mind → (D) 最完整。"},
{n:71,q:"What can be assumed about the location of the retreat?",qz:"關於靜修所的位置可以推斷出什麼？",o:["It is accessible by car.","It is in a desert.","It is on an island.","It is in the mountains."],oz:["可開車抵達。","位於沙漠中。","位於島上。","位於山區。"],a:2,ex:"「We are only accessible by ferry」只能搭渡輪抵達 → 最可能在島上。"}
]},
{ part: 7, title: "Part 7｜大樓管理員的警告信",
passage: `<p>To Whom It May Concern,</p><p>My name is Brian Zabbar, and I am the superintendent of this building. I am not sure who you are, so I have affixed this letter to the public recycling bin as a warning: Please do not throw your garbage in the recycling bin. —[1]— This is a little bothersome, but what really makes me furious is your disregard for the well-being of Mother Earth. —[2]— Previously, I have left polite notices and even purchased an additional garbage receptacle, clearly labeled it, and put it by the recycling bin. However, your inability to change your ways has forced my hand. —[3]— I have already installed a secret surveillance system nearby, and if you do not cease throwing your garbage in the recycling bin, I will be forced to report you to the owners of this building and request that you be evicted. —[4]—</p>`,
pz: `<p>敬啟者：</p><p>我是 Brian Zabbar，這棟大樓的管理員。我不知道你是誰，所以把這封信貼在公共資源回收桶上作為警告：請不要把垃圾丟進回收桶。—[1]— 每次你這麼做，我都得負責翻找回收物並重新分類。這有點麻煩，但真正讓我憤怒的是你對地球母親福祉的漠視。—[2]— 先前我已經貼過禮貌的告示，甚至還另外買了一個垃圾桶，清楚標示後放在回收桶旁。然而，你始終不肯改變，逼得我不得不採取行動。—[3]— 我已在附近裝設了隱藏式監視系統，如果你不停止把垃圾丟進回收桶，我將被迫向大樓業主檢舉你，並要求將你驅逐。—[4]—</p>`,
qs: [
{n:72,q:"Where did Brian leave his note?",qz:"Brian 把字條留在哪裡？",o:["In his office","On the recycling bin","On the person's door","On top of the garbage"],oz:["他的辦公室","回收桶上","那個人的門上","垃圾上面"],a:1,ex:"「I have affixed this letter to the public recycling bin」→ 貼在回收桶上。"},
{n:73,q:"How does Brian intend to find out who has been throwing garbage in the bin if he doesn't know who they are?",qz:"既然 Brian 不知道是誰，他打算如何找出把垃圾丟進回收桶的人？",o:["He'll wait by the bin.","He'll ask the building's owners.","He'll consult his hidden camera.","He'll look through the garbage to discover their personal information."],oz:["他會守在桶子旁。","他會問大樓業主。","他會查看隱藏攝影機。","他會翻垃圾找個人資料。"],a:2,ex:"「I have already installed a secret surveillance system nearby」→ 隱藏式監視器。"},
{n:74,q:"What does Brian think is the most irritating detail about this situation?",qz:"Brian 認為這件事最讓人惱火的是什麼？",o:["That he has to write rude notes","That he has to sort through garbage","That he may have to get someone evicted","That the person doesn't care about the environment"],oz:["他必須寫無禮的字條","他必須翻找垃圾","他可能得讓人被驅逐","對方不在乎環境"],a:3,ex:"「what really makes me furious is your disregard for the well-being of Mother Earth」→ 對方不關心環境。分類垃圾只是 a little bothersome。"},
{n:75,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Every time you do this, it is my responsibility to go through the recycling and sort it.\"",qz:"下列句子最適合放在哪個位置？\n「每次你這麼做，我都得負責翻找回收物並重新分類。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:0,ex:"do this 指「把垃圾丟進回收桶」，放在 [1] 緊接其後；之後 This is a little bothersome 指的就是分類這件麻煩事。"}
]},
{ part: 7, title: "Part 7｜Batman v Superman 影評",
passage: `<p>Reviewer: Kal McKay, <i>The Spruce Grove Daily Post</i><br>Grade: 4 out of 5 stars ★★★★<br>"Don't Believe the Hate, <i>Batman v Superman</i> is Great!"</p><p>At what point did the viewing populace suddenly become too good for melodrama? Yes, Zack Snyder's direction made <i>Batman v Superman</i> completely over the top, and yes, the film takes itself very seriously, but so what? Comic books have long been written in a severe tone, and this may be the main reason that legions of devotees take them as high art. Thus I find myself confused as to why the community of comic book fans would collectively turn their noses up at a serious-minded film such as this. At its core, this is an action movie that delivers its subject matter (an alien who fights a wealthy but mentally ill person) without a hint of the sarcasm which you find in other comic book movies. It is precisely this lack of irony that makes the film fun.</p><hr><p><b>By Jim Dobson →</b> <i>Batman v Superman</i> takes time-tested and beloved comic book icons and ruins them. What was Zack Snyder thinking? Batman is not the Batman I grew up with; he's borderline evil! I sat in the theater thinking, "Did Batman just kill someone? Batman doesn't kill." Well, here, he does—a lot. And Superman might as well have no personality at all. He barely even talks! Like their source material, comic book movies are exaggerations. They are supposed to be morally melodramatic. Their protagonists aren't heroes; they're superheroes! They're meant to show us the best thing to do in the worst situation. What did this movie teach? That the world is horrible and no one can do anything? The fans are right to hate this movie. Terrible. Just terrible.<br><b>2.5/10 TERRIBLE</b></p><p><i>596 comments</i><br>[Say Something Interesting]</p>`,
pz: `<p>影評人：Kal McKay，《Spruce Grove 日報》<br>評分：5 顆星中的 4 顆<br>「別相信那些惡評，《蝙蝠俠對超人》很棒！」</p><p>觀眾是從什麼時候開始突然看不起通俗劇了？沒錯，查克・史奈德的執導讓《蝙蝠俠對超人》完全誇張過頭，沒錯，這部片把自己看得非常嚴肅，但那又怎樣？漫畫長久以來都以嚴肅的語調寫成，這可能正是大批死忠粉絲把它們視為高雅藝術的主要原因。因此我很困惑，為什麼漫畫迷社群會集體對這樣一部嚴肅的電影嗤之以鼻。本質上，這是一部動作片，它呈現主題（一個外星人對抗一個富有但有精神疾病的人）時，完全沒有其他漫畫電影中那種冷嘲熱諷。正是這種不帶反諷的態度讓這部片好看。</p><hr><p><b>Jim Dobson →</b>《蝙蝠俠對超人》拿經得起時間考驗、深受喜愛的漫畫偶像來糟蹋。查克・史奈德在想什麼？這個蝙蝠俠不是我從小看到大的蝙蝠俠；他幾乎是邪惡的！我坐在電影院裡想：「蝙蝠俠剛剛殺人了嗎？蝙蝠俠是不殺人的。」嗯，在這部片裡他殺了——還殺了很多。而超人簡直毫無個性可言，他幾乎不說話！就像原著一樣，漫畫電影本來就是誇張的。它們應該在道德上是戲劇化的。主角不只是英雄，而是超級英雄！他們應該讓我們看到在最糟的處境下該做的最好的事。這部片教了我們什麼？世界很糟、誰也無能為力？粉絲討厭這部片是對的。糟透了，真的糟透了。<br><b>2.5/10 糟透了</b></p><p><i>596 則留言</i><br>[說點有趣的吧]</p>`,
qs: [
{n:76,q:"Who is Zack Snyder?",qz:"查克・史奈德是誰？",o:["A studio executive","The creator of Batman","A serious-minded critic","The director of the film"],oz:["片廠高層","蝙蝠俠的創作者","一位嚴肅的影評人","這部電影的導演"],a:3,ex:"「Zack Snyder's direction made Batman v Superman…」→ 他是導演。"},
{n:77,q:"Based on what both critics have written, what can we assume about this movie?",qz:"根據兩位影評人所寫，可以推斷這部電影如何？",o:["It was hated by many comic book fans.","It was not seen by most comic book fans.","It made more money than any other movie.","It was a polarizing movie among comic book fans."],oz:["很多漫畫迷討厭它。","大多數漫畫迷沒看過。","它比其他電影都賺錢。","它在漫畫迷之間評價兩極。"],a:0,ex:"McKay 說漫畫迷社群 collectively turn their noses up（集體嗤之以鼻），Dobson 說 The fans are right to hate this movie → 很多漫畫迷討厭。兩人都說粉絲討厭，並非「兩極」。"},
{n:78,q:"What was Kal McKay's overall impression of the movie?",qz:"Kal McKay 對這部電影的整體印象是什麼？",o:["Well done, despite its flaws","Not as good as others in the same genre","Too sarcastic for the story","Overly serious for a superhero movie"],oz:["儘管有缺點，仍拍得很好","不如同類型的其他電影","對這個故事來說太諷刺了","對超級英雄電影來說太嚴肅"],a:0,ex:"他給 4 顆星、標題說 is Great!，雖承認 over the top，但認為 so what → 有缺點但很好。"},
{n:79,q:"What kind of function does Jim Dobson think comic books and comic book movies should perform?",qz:"Jim Dobson 認為漫畫和漫畫電影應該發揮什麼功能？",o:["To teach people not to be so serious","To deliver incredible action sequences","To teach exaggerated ethical ideals","To inspire children to find respectable professions"],oz:["教人不要那麼嚴肅","呈現驚人的動作場面","傳達誇張化的道德理想","激勵孩子找到體面的職業"],a:2,ex:"他說漫畫電影 are exaggerations、supposed to be morally melodramatic、show us the best thing to do in the worst situation → 傳達誇張的道德理想。"},
{n:80,q:"What can we infer from the passages?",qz:"從這兩篇文章可以推論出什麼？",o:["The reviewers both hate comic books.","The reviewers write for different mediums.","The reviewers likely write for the news section.","The reviewers share the same opinion about Batman's persona."],oz:["兩位影評人都討厭漫畫。","兩位影評人為不同媒體撰稿。","兩位影評人可能都寫新聞版。","兩位對蝙蝠俠形象看法相同。"],a:1,ex:"McKay 為報紙（Daily Post）撰稿，Dobson 的評論有留言區（596 comments）→ 網路平台。兩人媒介不同。"}
]},
{ part: 7, title: "Part 7｜論文指導教授的往來信件",
passage: `<p>To: katelyngodwin@yahoo.com<br>From: sambloomsbury@gmail.com<br>Subject: An inquiry pertaining to your request</p><p>Dear Katelyn,</p><p>I am e-mailing to confirm that I have received your invitation to be on your thesis committee. Although I am flattered that you would want me to be your secondary advisor, I am a bit baffled as to why you would choose me. This is because the subject matter of your thesis "An Analysis of American Literary Preferences Pertaining to Translation Styles" seems to in no way align with my area of expertise (quantum computing). I will gladly accept your request if you can thoroughly explain (to my satisfaction) why you chose me in the first place.</p><p>Best wishes,<br>Sam Bloomsbury Ph.D.</p><hr><p>To: sambloomsbury@gmail.com<br>From: katelyngodwin@yahoo.com<br>Subject: Re: An inquiry pertaining to your request</p><p>Dear Professor Bloomsbury,</p><p>Truth be told, I wanted to include you on my committee for both logical and selfish reasons. Firstly, I believe that bringing in tangential or even seemingly unrelated disciplines can generate fresh perspectives in regards to problem solving. Secondly, it is my understanding that you are also skilled at programming algorithms which would prove useful to me as I need to sort and process large amounts of market data. Thirdly, of all the academics I could conceivably contact (both on and off this campus), you are by far the most prestigious, and so I believe that your mere affiliation with my research would elevate scholarly interest. If you are unable to accept my invitation, can you please put me in contact with a skilled programmer or a data analyst?</p><p>Sincerely,<br>Katelyn Godwin</p>`,
pz: `<p>收件者：katelyngodwin@yahoo.com<br>寄件者：sambloomsbury@gmail.com<br>主旨：關於你的請求的詢問</p><p>親愛的 Katelyn：</p><p>我寫信是要確認我已收到你邀請我加入論文委員會的邀請。雖然很榮幸你希望我擔任你的副指導教授，但我有點困惑你為何選擇我。因為你的論文主題「美國讀者對翻譯風格之文學偏好分析」似乎與我的專業領域（量子運算）毫不相關。如果你能徹底解釋（並讓我信服）你當初為何選擇我，我將樂意接受你的請求。</p><p>祝好<br>Sam Bloomsbury 博士</p><hr><p>收件者：sambloomsbury@gmail.com<br>寄件者：katelyngodwin@yahoo.com<br>主旨：回覆：關於你的請求的詢問</p><p>親愛的 Bloomsbury 教授：</p><p>老實說，我希望您加入委員會，既有合理的理由，也有私心。第一，我相信引入相關、甚至看似無關的學科，能在解決問題上帶來新觀點。第二，據我了解，您也擅長撰寫演算法程式，這對我會很有幫助，因為我需要整理與處理大量的市場資料。第三，在我可能聯絡到的所有學者中（不論校內外），您是目前最有聲望的一位，因此我相信光是您參與我的研究，就能提高學界的關注。如果您無法接受我的邀請，能否請您幫我聯繫一位厲害的程式設計師或資料分析師？</p><p>Katelyn Godwin 敬上</p>`,
qs: [
{n:81,q:"Why did Katelyn want Professor Bloomsbury as her secondary advisor?",qz:"Katelyn 為什麼想請 Bloomsbury 教授當副指導教授？",o:["The professor will bring a different perspective.","The professor's reputation would increase interest in her thesis.","The professor could help her analyze data.","All of the above"],oz:["教授會帶來不同觀點。","教授的聲望能提高論文關注度。","教授能幫她分析資料。","以上皆是"],a:3,ex:"她列了三個理由：Firstly 新觀點、Secondly 程式能力處理資料、Thirdly 聲望 → 三者皆是。"},
{n:82,q:"What is Katelyn's thesis about?",qz:"Katelyn 的論文主題是什麼？",o:["How well American readers can translate books","What kinds of books American readers would like to have translated","Which languages American readers prefer to have books translated from","What style of translation Americans prefer when reading translated books"],oz:["美國讀者翻譯書籍的能力","美國讀者希望哪類書被翻譯","美國讀者偏好從哪些語言翻譯過來的書","美國人閱讀譯本時偏好哪種翻譯風格"],a:3,ex:"題目 An Analysis of American Literary Preferences Pertaining to Translation Styles → 美國人對翻譯「風格」的偏好。"},
{n:83,q:"How will Professor Bloomsbury likely respond to Katelyn's reply?",qz:"Bloomsbury 教授可能會如何回應 Katelyn 的回信？",o:["He will organize a new thesis committee for Katelyn.","He will put Katelyn in contact with a skilled programmer.","He will reject the request since Katelyn ignored his requirement.","He will accept the request since Katelyn fulfilled his requirement."],oz:["他會為她另組論文委員會。","他會幫她聯繫程式設計師。","他會拒絕，因為她忽視了他的要求。","他會接受，因為她滿足了他的要求。"],a:3,ex:"教授的條件是「徹底解釋為何選他」，Katelyn 提出了三個完整理由 → 符合條件，可能會接受。"},
{n:84,q:"Which of the following substitutions is most synonymous with \"to my satisfaction\" in this context?",qz:"下列哪個替換與文中「to my satisfaction」意思最接近？",o:["If you can explain (and I am gleeful)","If you can explain (and I am flattered)","If you can explain (and I am convinced)","If you can explain (using the rhetoric proper to my discipline)"],oz:["如果你能解釋（而我很高興）","如果你能解釋（而我受寵若驚）","如果你能解釋（而我被說服）","如果你能解釋（用我領域適當的說法）"],a:2,ex:"explain to my satisfaction ＝ 解釋到讓我滿意、信服 → and I am convinced。"},
{n:85,q:"What can be assumed about Katelyn?",qz:"關於 Katelyn 可以推斷出什麼？",o:["She doesn't really care about her education.","Her thesis has been rejected by other professors.","She has read all of Professor Bloomsbury's work.","She is not very skilled at making computer programs."],oz:["她不太在乎自己的學業。","她的論文被其他教授拒絕過。","她讀過教授所有的著作。","她不太擅長寫電腦程式。"],a:3,ex:"她需要教授的程式能力，若教授不能參與，就請他介紹程式設計師或資料分析師 → 她自己不擅長寫程式。"}
]},
{ part: 7, title: "Part 7｜Grayson Floor Coverings 地毯",
passage: `<p><b>Grayson Floor Coverings has been the first name in flooring for over 50 years now, so when you buy carpet from us, you can rest assured you're getting a quality product.</b></p><p>New in store from Eagle Isles is the Vanguard line of commercial carpet. It's anti-static, stain-proof, and extremely durable, with a lifetime warranty. This carpet comes in 64 colors, 7 styles, and 3 levels of quality. So when you're ready to buy, pick out a color, choose a style, and select your quality level.</p><p>If you need installation for your flooring, we can take care of that too—including free labor for repeat customers. We offer the best prices in the state and a 90-day satisfaction guarantee. If, for any reason, you are not 100% happy with the job we do, contact Grayson Floor Coverings and we'll arrange for a replacement (sorry, no refunds).</p><table><tr><th colspan="4">Grayson Floor Coverings Customer Invoice</th></tr><tr><th>Quantity</th><th>Description</th><th>Unit Price</th><th>Total</th></tr><tr><td>Cadet blue level loop</td><td>x 80 linear feet</td><td>$34.68 per linear feet</td><td>$2,774.40</td></tr><tr><td>Steel grey level loop</td><td>x 80 linear feet</td><td>$35.64 per linear feet</td><td>$2,851.20</td></tr><tr><td>Raspberry red level loop</td><td>x 64 linear feet</td><td>$35.88 per linear feet</td><td>$2,296.32</td></tr><tr><td>Installation (1,000 square feet)</td><td>x 4</td><td>$749.00</td><td>$2,996.00</td></tr><tr><td>Labor</td><td></td><td>$999</td><td>$0.00</td></tr><tr><td colspan="3"></td><td>$10,917.92</td></tr></table><hr><p>From: Rick Pembrose &lt;tinyrick@gmale.com&gt;<br>To: Alfred Grayson &lt;Alfred@Graysonfloorings.com&gt;<br>Date: September 17<br>Subject: Pembrose carpet installation on 9/6</p><p>Hello Mr. Grayson,<br>I recently ordered 3,500 square feet of carpet for my office, plus installation. I have no problems with the carpet or the installation—your team did a fantastic job. The reason I am e-mailing you today is because I think that it is unfair to charge $2,996.00 for the carpet installation. Is there any way to adjust the price? Thank you for your consideration.</p><p>Sincerely,<br>Rick</p>`,
pz: `<p><b>Grayson 地板公司 50 多年來一直是地板業的第一品牌，所以向我們買地毯，您可以放心買到優質產品。</b></p><p>店內新上架 Eagle Isles 的 Vanguard 系列商用地毯。它防靜電、防污，而且極為耐用，享終身保固。這款地毯有 64 種顏色、7 種款式、3 種品質等級。準備購買時，請選顏色、挑款式，再選擇品質等級。</p><p>如果您的地板需要安裝，我們也能代勞——回頭客免收工資。我們提供全州最優惠的價格及 90 天滿意保證。如果您因任何原因對我們的施工不是 100% 滿意，請聯絡 Grayson 地板公司，我們將安排更換（抱歉，恕不退款）。</p><p><b>客戶發票</b>：學員藍圈絨 80 線性呎 × $34.68 = $2,774.40；鋼灰圈絨 80 線性呎 × $35.64 = $2,851.20；覆盆子紅圈絨 64 線性呎 × $35.88 = $2,296.32；安裝（每 1,000 平方呎）× 4 = $2,996.00；工資 $999 → $0.00；總計 $10,917.92。</p><hr><p>寄件者：Rick Pembrose<br>收件者：Alfred Grayson<br>日期：9 月 17 日<br>主旨：9/6 Pembrose 地毯安裝</p><p>Grayson 先生您好：<br>我最近為辦公室訂購了 3,500 平方呎的地毯並加購安裝。我對地毯和安裝都沒有問題——你們的團隊做得非常好。我今天寫信給您，是因為我認為地毯安裝收費 $2,996.00 不合理。請問價格是否有調整的可能？感謝您的考量。</p><p>Rick 敬上</p>`,
qs: [
{n:86,q:"In the advertisement, the phrase \"first name\" in paragraph 1, line 1, is closest in meaning to",qz:"廣告第 1 段第 1 行的「first name」意思最接近",o:["the best","the earliest","the cheapest","the smallest"],oz:["最好的","最早的","最便宜的","最小的"],a:0,ex:"the first name in flooring ＝ 業界第一品牌、首屈一指，後面接「保證優質產品」→ the best。"},
{n:87,q:"What can customers do if they don't like the carpet?",qz:"如果顧客不喜歡地毯，可以怎麼做？",o:["Get a refund","Switch it out for different carpet","Nothing","Buy more"],oz:["退款","換成別的地毯","什麼都不能做","再多買一些"],a:1,ex:"「we'll arrange for a replacement (sorry, no refunds)」→ 可以更換，不能退款。"},
{n:88,q:"What is probably true about Mr. Pembrose?",qz:"關於 Pembrose 先生，下列何者可能為真？",o:["He has ordered from Grayson Floor Coverings before.","He would like to exchange his carpet.","This is his first time buying carpet.","He was charged too much for labor."],oz:["他以前向 Grayson 訂購過。","他想換地毯。","這是他第一次買地毯。","他的工資被多收了。"],a:0,ex:"發票上 Labor 為 $0.00，而廣告說 free labor for repeat customers（回頭客免工資）→ 他是回頭客。"},
{n:89,q:"What color will most of Mr. Pembrose's office floors be?",qz:"Pembrose 先生的辦公室地板大部分會是什麼顏色？",o:["Red and green","Grey and red","Blue and red","Grey and blue"],oz:["紅與綠","灰與紅","藍與紅","灰與藍"],a:3,ex:"藍色 80、灰色 80、紅色只有 64 → 最多的是灰和藍。"},
{n:90,q:"How do we know that Mr. Pembrose's complaint is justified?",qz:"我們怎麼知道 Pembrose 先生的抱怨是合理的？",o:["He was charged four times too much for the installation.","He was charged for 4,500 square feet of carpet installation.","He was charged an additional $749.00 for the carpet installation.","His office is 3,500 square feet, but he was charged for 4,000 square feet."],oz:["安裝費被多收了四倍。","被收了 4,500 平方呎的安裝費。","安裝費被多收了 $749.00。","辦公室 3,500 平方呎，卻被收 4,000 平方呎。"],a:3,ex:"他訂 3,500 平方呎，安裝卻收 1,000 × 4 ＝ 4,000 平方呎的錢 → 多收了。"}
]},
{ part: 7, title: "Part 7｜學校該禁垃圾食物嗎？",
passage: `<table><tr><th colspan="4">In-School Junk Food Consumption among Barkley High School Students</th></tr><tr><th>Purchase of Junk Food at School (%)</th><th>Sweets</th><th>Salty Snacks</th><th>Soda</th></tr><tr><td>a. Did not buy any at school during the last week</td><td>86.5</td><td>88.8</td><td>93.6</td></tr><tr><td>b. 1 or 2 times during the last week in school</td><td>5.9</td><td>6.7</td><td>2.7</td></tr><tr><td>c. 3 or 4 times during the last week in school</td><td>3.6</td><td>2.1</td><td>1.5</td></tr><tr><td>d. 1 time per day</td><td>2.9</td><td>1.6</td><td>1.7</td></tr><tr><td>e. 2 times per day</td><td>0.6</td><td>0.4</td><td>0.2</td></tr><tr><td>f. 3 times per day</td><td>0.1</td><td>0.1</td><td>0.1</td></tr><tr><td>g. 4 or more times per day</td><td>0.4</td><td>0.3</td><td>0.2</td></tr></table><p><b>Should Junk Food Be Banned in Schools? People who are "For it"</b></p><p>ILoveCats99: School is more important than ever in forming a child's personal and social edification. Public schools have already incorporated lessons on other social issues such as citizenship into their curricula and also devote several hours a week to gym class, so why not teach classes on proper diet?</p><p>KimmyStardust29: Actually, many schools already teach that healthy eating and exercise are crucial to one's physical and mental well-being. However, their buildings are saturated with junk food vending machines, and their cafeterias are stuffed almost exclusively with fattening food. This is completely contradictory. It is time for schools to practice what they preach!</p><p><b>Should Junk Food Be Banned in Schools? People who are "Against it"</b></p><p>StevenHasPowers55: Though obesity is certainly on the rise, there is little evidence that state intervention within schools would yield any positive results. Moreover, based on my own experience, very few students seem to buy junk food at school. However, what the obesity epidemic reveals is a lack of responsibility on the part of American parents to practice healthy diets and lifestyles in their own homes.</p><p>JennyLovesSwimming11: Banning unhealthy foods in schools would not alleviate the problem. A more acceptable—and less drastic—solution to this nationwide problem would be for parents to practice physical activity and healthy living every day. Forbidding a substance alone will not teach prevention.</p>`,
pz: `<p><b>Barkley 高中學生在校內垃圾食物消費情形（%）</b>：上週在校都沒買——甜食 86.5、鹹零食 88.8、汽水 93.6；上週 1–2 次——5.9／6.7／2.7；上週 3–4 次——3.6／2.1／1.5；每天 1 次——2.9／1.6／1.7；每天 2 次——0.6／0.4／0.2；每天 3 次——0.1／0.1／0.1；每天 4 次以上——0.4／0.3／0.2。</p><p><b>學校應該禁止垃圾食物嗎？「贊成」方</b></p><p>ILoveCats99：學校在塑造孩子的個人與社會教養上比以往任何時候都重要。公立學校已將公民等其他社會議題納入課程，每週也撥出數小時上體育課，那為什麼不開正確飲食的課呢？</p><p>KimmyStardust29：事實上，很多學校已經教導健康飲食和運動對身心健康至關重要。然而，校內到處都是垃圾食物販賣機，餐廳裡幾乎全是會讓人發胖的食物。這完全自相矛盾。學校該是時候言行一致了！</p><p><b>學校應該禁止垃圾食物嗎？「反對」方</b></p><p>StevenHasPowers55：雖然肥胖確實在增加，但幾乎沒有證據顯示政府介入學校會帶來任何正面成效。而且根據我自己的經驗，似乎很少學生在學校買垃圾食物。肥胖流行真正顯示的是，美國父母沒有負起責任，在家裡實踐健康的飲食與生活方式。</p><p>JennyLovesSwimming11：在學校禁止不健康食物並不能緩解問題。對這個全國性問題，更能被接受、也較不激烈的解決方法，是父母每天實踐運動與健康生活。光是禁止某樣東西，並不能教會人預防。</p>`,
qs: [
{n:91,q:"What is the crux behind the junk food banning issue that is being debated?",qz:"這場垃圾食物禁令辯論背後的核心問題是什麼？",o:["Parents are too lazy.","Children are too fat.","Schools are too hypocritical.","The government is too detached."],oz:["父母太懶。","孩子太胖。","學校太虛偽。","政府太疏離。"],a:1,ex:"雙方爭論的起點都是兒童肥胖（obesity epidemic）→ 孩子太胖。其他選項只是單方論點。"},
{n:92,q:"Which user likely attends Barkley High School?",qz:"哪一位使用者可能就讀 Barkley 高中？",o:["ILoveCats99","KimmyStardust29","StevenHasPowers55","JennyLovesSwimming11"],oz:["ILoveCats99","KimmyStardust29","StevenHasPowers55","JennyLovesSwimming11"],a:2,ex:"Steven 說「based on my own experience, very few students seem to buy junk food at school」，與表格 Barkley 高中多數學生沒買的數據相符。"},
{n:93,q:"Which is NOT a point made in favor of junk food being banned in schools?",qz:"下列何者「不是」支持在學校禁止垃圾食物的論點？",o:["Providing healthy food is less expensive.","Serving it is hypocritical on the schools' part.","Banning it will teach students healthy eating habits.","Denying it will help the minds and bodies of children."],oz:["提供健康食物比較便宜。","學校販售垃圾食物很虛偽。","禁止它能教學生健康飲食習慣。","不提供它對孩子身心有益。"],a:0,ex:"贊成方從未提到「價格／成本」。(B) 是 Kimmy 的論點，(C)(D) 也與贊成方意見相符。"},
{n:94,q:"According to both users in the \"Against it\" section, what is really to blame for the obesity of children?",qz:"根據「反對」方兩位使用者，兒童肥胖真正該怪誰？",o:["Changing biology","Sugar and trans fat","Irresponsible parents","A broken education system"],oz:["生理變化","糖和反式脂肪","不負責任的父母","失靈的教育體系"],a:2,ex:"Steven 說是 a lack of responsibility on the part of American parents；Jenny 說應由父母實踐健康生活 → 父母的責任。"},
{n:95,q:"Which of the following statements best encapsulates the argument made by the user JennyLovesSwimming11?",qz:"下列哪一句最能概括 JennyLovesSwimming11 的論點？",o:["Obesity is an unstoppable generational problem.","Americans will not admit that they are becoming more irresponsible.","Restriction doesn't stop undesirable behavior, learned responsibility does.","By changing the parental zeitgeist, government policies can be manipulated."],oz:["肥胖是無法阻止的世代問題。","美國人不承認自己越來越不負責。","限制無法阻止不良行為，學到的責任感才能。","改變父母的時代思潮可操控政府政策。"],a:2,ex:"「Forbidding a substance alone will not teach prevention」+ 父母以身作則 → 禁止沒用，要靠學習負責。"}
]},
{ part: 7, title: "Part 7｜Miran Co. 人資總監職缺",
passage: `<p><b>Human Resources Director Position Opening at Miran Co.</b></p><p>Job Description:<br>Managing the Human Resources Department at Miran Co.'s central office</p><p>Responsibilities of the position include:<br>• Policy development<br>• Handling employee health care and insurance claims<br>• Preparing written communications</p><p>Qualifications:<br>• Ability to work with a team<br>• Strong leadership and managerial skills<br>• A degree in business administration, finance, or economics<br>• Must be a Canadian citizen<br>• A master's degree in business administration (preferred)<br>• Extensive linguistic abilities in both French and English (preferred)</p><p>How to Apply:<br>Submit a résumé and cover letter by mail or e-mail.</p><p>Caleb Endurian, (Current) Director of Human Resources<br>Miran Company<br>104 Avenue, 108 Street<br>Edmonton, Alberta, T5X 3SS<br>caleb.e@miran.com</p><hr><p><b>Katy Catsby</b><br>124 Ave, 127 Street, Edmonton, AB CA. TX6 3VP<br>Phone: 1-780 555, 4455<br>E-mail: kcatsby@gmail.com</p><p>Dear Mr. Endurian,<br>I am applying for the position of Human Resources Director at Miran Co.'s central office. I am a perfect fit for the position because I possess leadership skills, managerial experience, and a team-centric attitude.</p><p>In addition to having 10 years of managerial experience at Beyond Tech, where I ran the Business Development Department, I also hold both a bachelor of philosophy and MBA. I would be a valuable member of the Miran Co. team through innovating thinking, company loyalty, and enduring dedication to my career.</p><p>Please find attached to this e-mail my résumé to view my qualifications, experience, and references in greater detail. I look forward to hearing from you.</p><p>Sincerely,<br>Katy Catsby</p><hr><p>From: Caleb Endurian &lt;caleb.e@miran.com&gt;<br>To: Katy Catsby &lt;kcatsby@gmail.com&gt;<br>Date: April 13<br>Subject: Human Resources Director position</p><p>Dear Ms. Catsby,<br>I'm pleased to inform you that your application has been accepted. I would like to invite you in for an interview this Thursday.</p><p>We're looking for a candidate with many years of relevant experience. A familiarity with managerial processes will ensure a smooth transition. I also place a lot of value on long-term stability. FYI—French skills are a must. We're willing to provide language courses that range from beginner to advanced level.</p><p>I'm looking forward to our interview, and I hope it goes well.</p><p>Kind Regards,<br>Caleb Endurian</p>`,
pz: `<p><b>Miran 公司人力資源總監職缺</b></p><p>職務說明：管理 Miran 公司總部的人力資源部門</p><p>職責包括：<br>• 制定政策<br>• 處理員工健保與保險理賠<br>• 撰寫書面文件</p><p>資格條件：<br>• 具團隊合作能力<br>• 優秀的領導與管理能力<br>• 企管、財務或經濟學位<br>• 必須是加拿大公民<br>• 企管碩士（優先）<br>• 精通法語和英語（優先）</p><p>應徵方式：以郵寄或電子郵件寄送履歷與求職信。</p><p>Caleb Endurian，（現任）人力資源總監，Miran 公司，艾德蒙頓，亞伯達省</p><hr><p><b>Katy Catsby</b>（艾德蒙頓）</p><p>親愛的 Endurian 先生：<br>我應徵 Miran 公司總部的人力資源總監一職。我非常適合這個職位，因為我具備領導能力、管理經驗以及以團隊為中心的態度。</p><p>除了在 Beyond Tech 擁有 10 年管理經驗、負責經營業務開發部之外，我還擁有哲學學士和企管碩士學位。我能以創新思維、對公司的忠誠以及對職涯持久的投入，成為 Miran 團隊中有價值的一員。</p><p>隨信附上我的履歷，詳列我的資格、經歷與推薦人。期待您的回覆。</p><p>Katy Catsby 敬上</p><hr><p>寄件者：Caleb Endurian<br>收件者：Katy Catsby<br>日期：4 月 13 日<br>主旨：人力資源總監職位</p><p>Catsby 女士您好：<br>很高興通知您，您的申請已通過。我想邀請您本週四來面試。</p><p>我們在尋找具有多年相關經驗的人選。熟悉管理流程將確保交接順利。我也非常重視長期穩定性。順帶一提——法語能力是必備的。我們願意提供從初級到高級的語言課程。</p><p>期待我們的面試，祝順利。</p><p>Caleb Endurian 敬上</p>`,
qs: [
{n:96,q:"What can be assumed about Caleb Endurian?",qz:"關於 Caleb Endurian 可以推斷出什麼？",o:["He is being fired.","He is a strict HR director.","He is quitting due to salary issues.","He intends to find his own replacement."],oz:["他被解雇了。","他是嚴格的人資總監。","他因薪水問題辭職。","他打算找自己的接班人。"],a:3,ex:"他是「(Current) Director of HR」，卻負責招募人資總監，信中也說 ensure a smooth transition（順利交接）→ 在找接班人。離職原因文中沒提。"},
{n:97,q:"Which of the following would disqualify an applicant?",qz:"下列哪一項會使應徵者不符資格？",o:["Being monolingual","Being an American citizen","Having a finance degree","Experience with a competitor"],oz:["只會一種語言","是美國公民","擁有財務學位","曾在競爭對手公司工作"],a:1,ex:"資格寫 Must be a Canadian citizen → 美國公民不符資格。法語雖必備，但公司願意提供語言課程，所以單語不會直接被淘汰。"},
{n:98,q:"Which of the following does Katy NOT infer about herself?",qz:"下列哪一項是 Katy「沒有」提到關於自己的？",o:["She's bilingual.","She's a team player.","She's highly skilled.","She's a hard worker."],oz:["她會兩種語言。","她有團隊精神。","她能力很強。","她很努力。"],a:0,ex:"她提到 team-centric attitude（團隊）、leadership/managerial（能力）、enduring dedication（努力），但完全沒提語言能力。"},
{n:99,q:"Which of Katy's traits or qualifications is least related to the position to which she is applying?",qz:"Katy 的哪一項特質或資格與她應徵的職位最不相關？",o:["Her graduate degree","Her work experience","Her undergraduate degree","Her work ethic and attitude"],oz:["她的研究所學位","她的工作經驗","她的大學學位","她的工作態度"],a:2,ex:"職缺要求企管、財務或經濟學位，而她的大學學位是「哲學」→ 最不相關。MBA 則是加分條件。"},
{n:100,q:"Which of the following is a quality that Katy possesses which would likely impress Mr. Endurian?",qz:"下列哪一項是 Katy 擁有、且可能讓 Endurian 先生印象深刻的特質？",o:["Company loyalty","Innovative thinking","French language ability","Knowledge of government policy"],oz:["對公司的忠誠","創新思維","法語能力","政府政策的知識"],a:0,ex:"Endurian 說 I also place a lot of value on long-term stability（重視長期穩定）→ 與 Katy 的 company loyalty 相符。"}
]}
]
});
